// Parse the model's JSON (tolerating stray code fences) and validate ids against what the app sent.
const body = $('Webhook').item.json.body
const raw = String($input.first().json.output ?? '')
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim()
let parsed
try {
  parsed = JSON.parse(cleaned)
} catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/)
  if (!m) return [{ json: { ok: false, error: 'Model did not return JSON', raw } }]
  try { parsed = JSON.parse(m[0]) } catch { return [{ json: { ok: false, error: 'Model returned malformed JSON', raw } }] }
}
if (parsed.error) return [{ json: { ok: false, error: String(parsed.error) } }]

const accountIds = new Set((body.accounts || []).map(a => a.id))
const categoryIds = new Set((body.categories || []).map(c => c.id))
const amount = Number(parsed.amount)
if (!Number.isFinite(amount) || amount === 0) return [{ json: { ok: false, error: 'Could not work out the amount' } }]
const accountId = accountIds.has(parsed.accountId) ? parsed.accountId : body.defaultAccountId
const fallbackCategory = (body.categories || []).find(c => /running budget/i.test(c.name))
const categoryId = categoryIds.has(parsed.categoryId) ? parsed.categoryId : (fallbackCategory && fallbackCategory.id)
if (!categoryId) return [{ json: { ok: false, error: 'No usable category' } }]
const occurredAt = /^\d{4}-\d{2}-\d{2}$/.test(String(parsed.occurredAt)) ? parsed.occurredAt : body.today

return [{ json: {
  ok: true,
  transaction: { accountId, categoryId, amount, note: String(parsed.note || body.text).slice(0, 120), occurredAt },
  confidence: parsed.confidence === 'low' ? 'low' : 'high',
  explanation: String(parsed.explanation || ''),
} }]
